feed:
  {{ site.title_suffix }}


  {{ env.base_url }}
  {{ feed_updated.isoformat() }}T00:00:00{{ site.timezone }}
  {{ site.author }}
{% for post in posts %}

    {{ post.title }}

    {{ env.base_url }}{{ post.path }}
    {{ post.published.isoformat() }}T{{ post.time or '00:00' }}:00{{ post.timezone }}
{% if post.updated %}
    {{ post.updated.isoformat() }}T00:00:00{{ site.timezone }}
{% else %}
    {{ post.published.isoformat() }}T{{ post.time or '00:00' }}:00{{ post.timezone }}
{% endif %}
    {{ post.description }}

{% endfor %}
